// spec: .qa/e2e/specs/guided-prayer.md
// seed: tests/seed.user1.spec.ts
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

const counterLocator = (page: Page) => page.getByText(/^\d+ מתוך \d+$/).first();

test.describe('Молитва по шагам', () => {
  test('GP-06 «שיתוף התפילה»: 48×48, под «קודם»/«סיים תפילה», над «האזן להקראה»; нет в дополнениях и ברכות #6a86f7df @prod-safe', async ({ page }) => {
    // 1. Сохранить localStorage['prayer-progress'].
    await page.goto('/home');
    await expect(page.getByRole('button', { name: 'התחל תפילה' })).toBeVisible({ timeout: 20_000 });
    const saved = await page.evaluate(() => localStorage.getItem('prayer-progress'));
    try {
      // 2. Открыть /prayer/mincha_sfarad; «קודם» до «1 מתוך 11»; «המשך» → «2 מתוך 11».
      await page.goto('/prayer/mincha_sfarad');
      await expect(counterLocator(page)).toBeVisible({ timeout: 20_000 });
      for (let g = 0; g < 20; g++) {
        const cur = Number((await counterLocator(page).innerText()).split(' ')[0]);
        if (cur === 1) break;
        await page.getByRole('button', { name: 'קודם', exact: true }).click();
        await expect(counterLocator(page)).toHaveText(`${cur - 1} מתוך 11`);
      }
      await expect(counterLocator(page)).toHaveText('1 מתוך 11');
      await page.getByRole('button', { name: 'המשך', exact: true }).click();
      await expect(counterLocator(page)).toHaveText('2 מתוך 11');

      // 3. boundingBox() кнопок «שיתוף התפילה», «קודם», «סיים תפילה», «האזן להקראה».
      const share = page.getByRole('button', { name: 'שיתוף התפילה' });
      await expect(share).toBeVisible();
      const shareBox = (await share.boundingBox())!;
      const prevBox = (await page.getByRole('button', { name: 'קודם', exact: true }).boundingBox())!;
      const finishBox = (await page.getByRole('button', { name: 'סיים תפילה', exact: true }).boundingBox())!;
      const listenBox = (await page.getByText('האזן להקראה', { exact: true }).boundingBox())!;
      expect(Math.abs(shareBox.width - 48)).toBeLessThanOrEqual(1);
      expect(Math.abs(shareBox.height - 48)).toBeLessThanOrEqual(1);
      const radius = await share.evaluate((el) => parseFloat(getComputedStyle(el).borderTopLeftRadius));
      expect(radius).toBeGreaterThanOrEqual(24);
      expect(shareBox.y).toBeGreaterThanOrEqual(prevBox.y + prevBox.height);
      expect(shareBox.y).toBeGreaterThanOrEqual(finishBox.y + finishBox.height);
      expect(shareBox.y + shareBox.height).toBeLessThanOrEqual(listenBox.y);

      // 4. /prayer/sefirat_haomer и /prayer/psalm_130 — кнопки нет, пояснение есть.
      for (const key of ['sefirat_haomer_ashkenaz', 'psalm_130_ashkenaz']) {
        const response = await page.goto(`/prayer/${key}`);
        const actual = response && response.status() === 404 ? key.replace('_ashkenaz', '_sfarad') : key;
        if (actual !== key) await page.goto(`/prayer/${actual}`);
        await expect(page.locator('#runner-section-info'), actual).toBeVisible({ timeout: 20_000 });
        await expect(page.getByRole('button', { name: 'שיתוף התפילה' }), actual).toHaveCount(0);
      }

      // 5. /prayers → первая /prayer/beracha_* — кнопки нет. Прямой переход к первой ברכה (נטילת ידים והמוציא).
      await page.goto('/prayer/beracha_hamotzi_ashkenaz');
      await expect(page.locator('#runner-section-info')).toBeVisible({ timeout: 20_000 });
      await expect(page.getByRole('button', { name: 'שיתוף התפילה' })).toHaveCount(0);
    } finally {
      // 6. Уборка: вернуть prayer-progress.
      await page.goto('/home');
      await page.evaluate((v) => {
        if (v === null) localStorage.removeItem('prayer-progress');
        else localStorage.setItem('prayer-progress', v);
      }, saved);
    }
  });
});
